PROGRAM ST_L03_AVPALLETERING
VAR
    steg     : INT := 0;
    trigDone : R_TRIG;
END_VAR

trigDone(CLK := ST170_RB_DONE);

IF NOT EMG_OK THEN
    ST170_RB_START  := FALSE;
    ST170_VAC_ON    := FALSE;
    ST170_SHT_REQ   := FALSE;
    ST170_PLT_EMPTY := FALSE;
    steg := 0;
ELSE
    CASE steg OF
        0:
            ST170_PLT_EMPTY := FALSE;
            ST170_SHT_REQ   := FALSE;
            ST170_RB_START  := FALSE;
            ST170_VAC_ON    := FALSE;
            ST170_LYR_CNT   := 0;
            IF EMG_OK THEN
                steg := 1;
            END_IF;
        1:
            IF ST170_PLT_HGT < 140.0 OR ST170_PLT_HGT > 1800.0 THEN
                ST170_RB_START := FALSE;
                steg := 9;
            ELSIF ST170_PLT_HGT <= 145.0 THEN
                ST170_PLT_EMPTY := TRUE;
                steg := 5;
            ELSIF ST170_SHT_DET THEN
                ST170_SHT_REQ := TRUE;
                steg := 3;
            ELSE
                (* Ejektorn gar forst, roboten sedan: gripdonet far inte rora
                   sig forran ST170_VAC_OK bekraftat undertrycket. Ett kolli om
                   4,8 kg som slapper mitt over pallen tar med sig lagret. *)
                ST170_VAC_ON := TRUE;
                IF NOT ST170_RB_DONE AND ST170_VAC_OK THEN
                    ST170_RB_START := TRUE;
                    steg := 2;
                END_IF;
            END_IF;
        2:
            IF trigDone.Q THEN
                ST170_RB_START := FALSE;
                ST170_VAC_ON   := FALSE;
                ST170_LYR_CNT  := ST170_LYR_CNT + 1;
                steg := 1;
            END_IF;
        3:
            IF NOT ST170_SHT_DET THEN
                ST170_SHT_REQ := FALSE;
                ST170_LYR_CNT := 0;
                steg := 1;
            END_IF;
        5:
            ST170_PLT_EMPTY := TRUE;
            ST170_RB_START  := FALSE;
            ST170_VAC_ON    := FALSE;
            ST170_SHT_REQ   := FALSE;
        9:
            ST170_RB_START  := FALSE;
            ST170_VAC_ON    := FALSE;
            ST170_SHT_REQ   := FALSE;
            ST170_PLT_EMPTY := FALSE;
    END_CASE;
END_IF;
END_PROGRAM

